class BigNumCalculator:

    @staticmethod
    def add(num1, num2):
        """
        Adds two big numbers.
        :param num1: The first number to add,str.
        :param num2: The second number to add,str.
        :return: The sum of the two numbers,str.
        >>> bigNum = BigNumCalculator()
        >>> bigNum.add("12345678901234567890", "98765432109876543210")
        '111111111011111111100'

        """
        # Remove any leading/trailing whitespace and convert to string
        num1 = str(num1).strip()
        num2 = str(num2).strip()

        # Handle empty or invalid input
        if not num1 or not num2:
            return "0"

        # Check for negative numbers using manual comparison
        def get_sign(n):
            return -1 if n.startswith('-') else 1

        sign1 = get_sign(num1)
        sign2 = get_sign(num2)

        # Get absolute values manually
        def get_absolute(n):
            if n.startswith('-'):
                return n[1:]
            return n

        abs1 = get_absolute(num1)
        abs2 = get_absolute(num2)

        # Compare magnitudes for subtraction case
        def bigger_length(s1, s2):
            if len(s1) > len(s2):
                return s1
            elif len(s1) < len(s2):
                return s2
            else:
                return s1 if s1 >= s2 else s2

        bigger = bigger_length(abs1, abs2)
        smaller = get_absolute(num2) if bigger == abs1 else get_absolute(num1)

        # Determine result sign and magnitude
        if sign1 == sign2:
            # Same sign: add magnitudes, keep sign
            return ('-' if sign1 == -1 else '') + _add_magnitudes(bigger, smaller)
        else:
            # Different signs: subtract smaller from larger
            diff = _subtract_magnitudes(bigger, smaller)
            # Result sign follows the larger magnitude's sign
            if bigger == abs1:
                return '-' + diff if sign1 == -1 else diff
            else:
                return '-' + diff if sign2 == -1 else diff

    @staticmethod
    def subtract(num1, num2):
        return None

    @staticmethod
    def multiply(num1, num2):
        return None
